#include <stdlib.h>
typedef struct Node { int data; struct Node *next; } Node;
Node *insert(Node *head, int value, int allocation_success) {
    Node *p = allocation_success ? malloc(sizeof *p) : NULL;
    if (p == NULL) return head;
    p->data = value;
    p->next = head;
    return p;
}
int main(void) {
    Node *caller_head = NULL;
    caller_head = insert(caller_head, -3, 0);
    caller_head = insert(caller_head, 5, 1);
    (void)caller_head;
    return 0;
}
